import { useEffect, useState } from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import type { BufferPreset, VideoFit } from '@mfp/core';
import { focusRing } from '../nav/focusRing.js';
import { useNavigation } from '../nav/navigationStack.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useProvider } from '../runtime/useProvider.js';
import { useLists } from '../state/lists.js';
import { useSession } from '../state/session.js';
import { useSettings, type AppSettings } from '../state/settings.js';
import { ORDEM_MAX_RES } from '../player/resolution.js';
import { useSync } from '../state/sync.js';
import { useCatalog } from '../state/catalog.js';
import { useToast } from '../components/Toast.js';
import { PinModal } from '../components/PinModal.js';
import { ForgotPinModal } from '../components/ForgotPinModal.js';
import { useParental } from '../state/parental.js';
import { t, type TextKey } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

const APP_VERSION = '0.1.0-dev';

/** Etapas do modal de PIN em Configurações. */
type PinFluxo = 'novo' | 'confirmar' | 'desativar' | 'destravar' | 'trocar-atual';

const TITULOS: Record<PinFluxo, { title: TextKey; body: TextKey }> = {
  novo: { title: 'parental.titleNew', body: 'parental.bodyNew' },
  confirmar: { title: 'parental.titleConfirm', body: 'parental.bodyConfirm' },
  desativar: { title: 'parental.titleDisable', body: 'parental.bodyDisable' },
  destravar: { title: 'parental.titleUnlock', body: 'parental.bodyUnlock' },
  'trocar-atual': { title: 'parental.titleCurrent', body: 'parental.bodyCurrent' },
};

export function Settings({ listId }: { listId: string }) {
  const rt = useRuntime();
  const getProvider = useProvider();
  const settings = useSettings();
  const account = useSession((s) => s.account);
  const lists = useLists((s) => s.lists);
  const push = useNavigation((s) => s.push);
  const runSync = useSync((s) => s.run);
  const loadHome = useCatalog((s) => s.loadHome);
  const show = useToast((s) => s.show);
  const list = lists.find((l) => l.id === listId);
  const parental = useParental();
  const [pinFluxo, setPinFluxo] = useState<PinFluxo | null>(null);
  const [pinErro, setPinErro] = useState<string | undefined>();
  const [pinNovo, setPinNovo] = useState('');
  /** Linha que abriu o modal, para devolver o foco ao fechar. */
  const [pinOrigem, setPinOrigem] = useState('parental-toggle');
  /** "Esqueci o PIN" — troca o PinModal por este enquanto aberto. */
  const [esqueciAberto, setEsqueciAberto] = useState(false);

  useEffect(() => {
    void settings.load(rt);
  }, [rt, settings]);

  useEffect(() => {
    if (!parental.carregado) void parental.load(rt);
  }, [rt, parental]);

  /** Recarrega as telas que dependem do catálogo depois de mudar a política. */
  const recarregar = () => void loadHome(rt, listId);

  const fecharPin = () => {
    setPinFluxo(null);
    setPinErro(undefined);
    setPinNovo('');
    // sem isto o foco cai na primeira linha da tela, longe de onde o usuário estava
    void setFocus(pinOrigem);
  };

  /** Abre o modal guardando de onde veio. */
  const abrirPin = (fluxo: PinFluxo, origem: string) => {
    setPinErro(undefined);
    setPinOrigem(origem);
    setPinFluxo(fluxo);
  };

  /** Troca o PinModal pelo fluxo "esqueci o PIN" — mesma origem/foco de retorno. */
  const abrirEsqueci = () => {
    setPinFluxo(null);
    setEsqueciAberto(true);
  };

  const fecharEsqueci = () => {
    setEsqueciAberto(false);
    void setFocus(pinOrigem);
  };

  const aoConfirmarPin = (pin: string) => {
    void (async () => {
      setPinErro(undefined);
      if (pinFluxo === 'novo') {
        setPinNovo(pin);
        setPinFluxo('confirmar');
        return;
      }
      if (pinFluxo === 'confirmar') {
        if (pin !== pinNovo) {
          setPinErro(t('parental.mismatch'));
          setPinFluxo('novo');
          setPinNovo('');
          return;
        }
        await parental.ativar(rt, pin);
        recarregar();
        show(t('parental.enabled'), 'success');
        fecharPin();
        return;
      }
      if (pinFluxo === 'desativar') {
        if (!(await parental.desativar(rt, pin))) return setPinErro(t('parental.wrong'));
        recarregar();
        show(t('parental.disabled'), 'success');
        return fecharPin();
      }
      if (pinFluxo === 'destravar') {
        if (!(await parental.destravar(rt, pin))) return setPinErro(t('parental.wrong'));
        recarregar();
        show(t('parental.unlocked'), 'success');
        return fecharPin();
      }
      if (pinFluxo === 'trocar-atual') {
        if (!(await parental.destravar(rt, pin))) return setPinErro(t('parental.wrong'));
        setPinFluxo('novo');
      }
    })();
  };

  const { ref, focusKey } = useFocusable({ focusKey: 'settings', trackChildren: true });

  const bufferLabels: Record<BufferPreset, string> = {
    curto: t('settings.bufferShort'),
    medio: t('settings.bufferMedium'),
    longo: t('settings.bufferLong'),
  };
  const cycleBuffer = () => {
    const order: BufferPreset[] = ['curto', 'medio', 'longo'];
    const next = order[(order.indexOf(settings.buffer) + 1) % order.length]!;
    void settings.update(rt, { buffer: next });
  };

  const fitLabels: Record<VideoFit, string> = {
    original: t('player.fitOriginal'),
    fill: t('player.fitFill'),
    '16:9': t('player.fit169'),
    '4:3': t('player.fit43'),
  };
  const cycleFit = () => {
    const order: VideoFit[] = ['original', 'fill', '16:9', '4:3'];
    const next = order[(order.indexOf(settings.videoFit) + 1) % order.length]!;
    void settings.update(rt, { videoFit: next });
  };

  const resLabel = (r: AppSettings['maxVideoHeight']): string => {
    if (r === 'auto') return t('settings.resAuto');
    if (r === 0) return t('settings.resUnlimited');
    return `${r}p`;
  };
  const cycleRes = () => {
    const i = ORDEM_MAX_RES.indexOf(settings.maxVideoHeight);
    void settings.update(rt, {
      maxVideoHeight: ORDEM_MAX_RES[(i + 1) % ORDEM_MAX_RES.length]!,
    });
  };

  // Spec 003 LG-022: chute pragmático, sem cota oficial da LG pra mirar —
  // ajustável aqui pra dar pra estressar em campo sem depender de um novo
  // build a cada tentativa. `0` = sem limite (não confundir com `slice(0,0)`,
  // ver `CatalogSync.persistComLimite`).
  const ORDEM_CAP_CATALOGO = [100, 300, 500, 1000, 2000, 5000, 0] as const;
  const capLabel = (n: number): string =>
    n === 0 ? t('settings.catalogCapUnlimited') : String(n);
  const cycleCap = () => {
    const i = ORDEM_CAP_CATALOGO.indexOf(
      settings.catalogItemCapOldDevices as (typeof ORDEM_CAP_CATALOGO)[number],
    );
    const proximo = ORDEM_CAP_CATALOGO[(Math.max(i, 0) + 1) % ORDEM_CAP_CATALOGO.length]!;
    void settings.update(rt, { catalogItemCapOldDevices: proximo }).then(() => {
      if (useSettings.getState().saveError) show(t('settings.saveError'), 'error');
    });
  };

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          maxWidth: '48rem',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1.5rem'),
        }}
      >
        <h1>{t('settings.title')}</h1>

        <Section title={t('settings.secPlayback')}>
          <Row
            fk="set-autoplay"
            label={t('settings.autoplayNext')}
            value={settings.autoplayNext ? t('common.on') : t('common.off')}
            onPress={() =>
              void settings.update(rt, { autoplayNext: !settings.autoplayNext })
            }
          />
          <Row
            fk="set-buffer"
            label={t('settings.buffer')}
            value={bufferLabels[settings.buffer]}
            onPress={cycleBuffer}
          />
          <Row
            fk="set-videofit"
            label={t('settings.videoFit')}
            value={fitLabels[settings.videoFit]}
            onPress={cycleFit}
          />
          <Row
            fk="set-maxres"
            label={t('settings.maxResolution')}
            value={resLabel(settings.maxVideoHeight)}
            onPress={cycleRes}
          />
          <Row
            fk="set-epg-list"
            label={t('settings.epgInList')}
            value={settings.epgInList ? t('common.on') : t('common.off')}
            onPress={() => void settings.update(rt, { epgInList: !settings.epgInList })}
          />
        </Section>

        <Section title={t('settings.secNetwork')}>
          <Row
            fk="set-list"
            label={t('settings.manageLists')}
            value={
              lists.length > 1
                ? t('settings.listCount', { n: lists.length, ativa: list?.name ?? '—' })
                : (list?.name ?? '—')
            }
            onPress={() => push({ name: 'manageLists' })}
          />
          <Row
            fk="set-format"
            label={t('settings.streamFormat')}
            value={settings.streamFormat}
            onPress={() =>
              void settings.update(rt, {
                streamFormat: settings.streamFormat === 'm3u8' ? 'ts' : 'm3u8',
              })
            }
          />
          <Row
            fk="set-refresh"
            label={t('settings.refreshNow')}
            onPress={() => {
              show(t('settings.refreshNow'), 'info');
              void (async () => {
                const { provider } = await getProvider();
                await runSync(rt, listId, provider, { force: true });
                await loadHome(rt, listId);
                show('✓', 'success');
              })();
            }}
          />
          <Row
            fk="set-clear"
            label={t('settings.clearCache')}
            onPress={() => {
              // LS-RF-15 (spec 005): limpeza reconstruível — preserva favoritos e
              // progresso. Ao contrário do antigo `wipeList`, é segura pra liberar
              // espaço quando o IndexedDB está perto/estourando a cota (LG-022).
              void rt.db
                .wipeReconstructibleCache(listId)
                .then(() => show('✓', 'success'));
            }}
          />
          <Row
            fk="set-test"
            label={t('settings.testConnection')}
            onPress={() => {
              void (async () => {
                try {
                  const { provider } = await getProvider();
                  const acc = await provider.authenticate();
                  show(`${acc.status} · ${acc.maxConnections} con.`, 'success');
                } catch {
                  show('falhou', 'error');
                }
              })();
            }}
          />
          <Row
            fk="set-catalog-cap"
            label={t('settings.catalogCap')}
            value={capLabel(settings.catalogItemCapOldDevices)}
            onPress={cycleCap}
          />
        </Section>

        <Section title={t('parental.section')}>
          <Row
            fk="parental-toggle"
            label={t('parental.blockAdult')}
            value={parental.ligado ? t('parental.on') : t('parental.off')}
            onPress={() =>
              // desligar exige o PIN; ligar pede para criar um
              abrirPin(parental.ligado ? 'desativar' : 'novo', 'parental-toggle')
            }
          />
          {parental.ligado && (
            <Row
              fk="parental-show"
              label={parental.destravado ? t('parental.hide') : t('parental.show')}
              onPress={() => {
                if (parental.destravado) {
                  parental.travar(rt);
                  recarregar();
                  show(t('parental.relocked'), 'info');
                  return;
                }
                abrirPin('destravar', 'parental-show');
              }}
            />
          )}
          {parental.ligado && (
            <Row
              fk="parental-change"
              label={t('parental.changePin')}
              onPress={() => {
                abrirPin('trocar-atual', 'parental-change');
              }}
            />
          )}
        </Section>

        <Section title={t('settings.secAbout')}>
          <Row fk="set-version" label={t('settings.version')} value={APP_VERSION} />
          {account && (
            <>
              <Row
                fk="set-acc-status"
                label={t('settings.account')}
                value={account.status}
              />
              {account.expiresAt && (
                <Row
                  fk="set-acc-exp"
                  label={t('settings.expiresOn', {
                    date: new Date(account.expiresAt).toLocaleDateString('pt-BR'),
                  })}
                  value=""
                />
              )}
              <Row
                fk="set-acc-con"
                label={t('settings.maxConnections', { n: account.maxConnections })}
                value=""
              />
            </>
          )}
        </Section>

        <Section title={t('settings.secAppearance')}>
          <Row
            fk="set-contrast"
            label={t('settings.highContrast')}
            value={settings.highContrast ? t('common.on') : t('common.off')}
            onPress={() =>
              void settings.update(rt, { highContrast: !settings.highContrast })
            }
          />
          <Row
            fk="set-motion"
            label={t('settings.reducedMotion')}
            value={settings.reducedMotion ? t('common.on') : t('common.off')}
            onPress={() =>
              void settings.update(rt, { reducedMotion: !settings.reducedMotion })
            }
          />
        </Section>
      </div>

      {pinFluxo && (
        <PinModal
          title={t(TITULOS[pinFluxo].title)}
          body={t(TITULOS[pinFluxo].body)}
          attemptsLeft={parental.tentativasRestantes}
          waitUntil={parental.bloqueadoAte}
          error={pinErro}
          onConfirm={aoConfirmarPin}
          onCancel={fecharPin}
          // Só faz sentido "esquecer" um PIN que já existe — não no fluxo de
          // criação ('novo'/'confirmar'), onde ainda não há nada pra esquecer.
          onForgot={
            pinFluxo === 'desativar' ||
            pinFluxo === 'destravar' ||
            pinFluxo === 'trocar-atual'
              ? abrirEsqueci
              : undefined
          }
        />
      )}

      {esqueciAberto && (
        <ForgotPinModal
          attemptsLeft={parental.tentativasRestantes}
          waitUntil={parental.bloqueadoAte}
          onCheckPassword={(senha) => parental.verificarSenhaDaLista(rt, listId, senha)}
          onConfirmNewPin={(senha, novoPin) => {
            void (async () => {
              const ok = await parental.resetarComSenhaDaLista(
                rt,
                listId,
                senha,
                novoPin,
              );
              if (!ok) return; // senha mudou entre as duas chamadas (raro); modal segue aberto
              recarregar();
              show(t('parental.resetDone'), 'success');
              fecharEsqueci();
            })();
          }}
          onCancel={fecharEsqueci}
        />
      )}
    </FocusContext.Provider>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section
      className={gapColClass}
      style={{ display: 'flex', flexDirection: 'column', ...gapVar('0.5rem') }}
    >
      <h3 style={{ fontSize: 'var(--fs-section)', color: 'var(--text-secondary)' }}>
        {title}
      </h3>
      {children}
    </section>
  );
}

function Row({
  fk,
  label,
  value,
  onPress,
}: {
  fk: string;
  label: string;
  value?: string;
  onPress?: () => void;
}) {
  const { ref, focused } = useFocusable({
    focusKey: fk,
    onEnterPress: onPress,
    focusable: !!onPress,
  });
  return (
    <div
      ref={ref}
      onClick={pressWithFocus(fk, onPress)}
      className={gapRowClass}
      style={{
        display: 'flex',
        justifyContent: 'space-between',
        padding: '0.8rem 1rem',
        borderRadius: 'var(--radius-sm)',
        ...gapVar('1rem'),
        background: focused ? 'var(--bg-raised)' : 'var(--bg-panel)',
        cursor: onPress ? 'pointer' : 'default',
        ...focusRing(focused),
      }}
    >
      <span>{label}</span>
      {value != null && <span style={{ color: 'var(--accent)' }}>{value}</span>}
    </div>
  );
}
