import { useEffect, useState, type ReactNode } from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import { focusRing } from '../nav/focusRing.js';
import { useBackHandler } from '../nav/backStack.js';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { FocusButton } from './FocusButton.js';
import { OnScreenKeyboard } from './OnScreenKeyboard.js';
import { BackspaceIcon } from './icons.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

export interface ForgotPinModalProps {
  /** Confere a senha; `true` avança para o passo do novo PIN. */
  onCheckPassword: (senha: string) => Promise<boolean>;
  /** Só chamado depois que `onCheckPassword` já confirmou a senha. */
  onConfirmNewPin: (senha: string, novoPin: string) => void;
  onCancel: () => void;
  /** Quantas tentativas ainda restam antes da espera (RF-32, mesmo limite do PIN). */
  attemptsLeft?: number;
  waitUntil?: number;
}

const DIGITOS = 4;

/**
 * "Esqueci o PIN" do controle parental: confere a senha da lista Xtream (o
 * único segredo que já existe, único por instalação — ver a nota em
 * `state/parental.ts`) e só then deixa escolher um PIN novo. Duas etapas no
 * mesmo modal — senha primeiro, para o usuário não digitar 4 dígitos novos
 * pra só então descobrir que errou a senha.
 */
export function ForgotPinModal({
  onCheckPassword,
  onConfirmNewPin,
  onCancel,
  attemptsLeft,
  waitUntil = 0,
}: Readonly<ForgotPinModalProps>) {
  const [etapa, setEtapa] = useState<'senha' | 'pin'>('senha');
  const [senha, setSenha] = useState('');
  const [pin, setPin] = useState('');
  const [erroSenha, setErroSenha] = useState<string | undefined>();
  const [conferindo, setConferindo] = useState(false);

  const { ref, focusKey } = useFocusable({
    focusKey: 'forgot-modal',
    trackChildren: true,
    saveLastFocusedChild: true,
  });

  useBackHandler(onCancel);

  useEffect(() => {
    setFocus(etapa === 'senha' ? 'forgot-kb' : 'forgot-pin-1');
  }, [etapa]);

  const [agora, setAgora] = useState(() => Date.now());
  useEffect(() => {
    if (waitUntil <= agora) return;
    const id = window.setInterval(() => setAgora(Date.now()), 500);
    return () => window.clearInterval(id);
  }, [waitUntil, agora]);
  const faltam = Math.max(0, Math.ceil((waitUntil - agora) / 1000));

  const confirmarSenha = () => {
    if (!senha || conferindo) return;
    setConferindo(true);
    setErroSenha(undefined);
    void onCheckPassword(senha).then((ok) => {
      setConferindo(false);
      if (ok) setEtapa('pin');
      else setErroSenha(t('parental.wrongPassword'));
    });
  };

  const digitarPin = (d: string) => {
    setPin((p) => {
      const novo = p.length >= DIGITOS ? p : p + d;
      if (novo.length === DIGITOS) {
        setTimeout(() => onConfirmNewPin(senha, novo), 0);
      }
      return novo;
    });
  };

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        role="dialog"
        aria-modal
        aria-label={t('parental.titleForgot')}
        style={{
          position: 'fixed',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          zIndex: 50,
          background: 'var(--bg-scrim)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '2vh 4vw',
        }}
      >
        <div
          className={gapColClass}
          style={{
            background: 'var(--bg-panel)',
            border: '1px solid var(--border-subtle)',
            borderRadius: 'var(--radius-lg)',
            padding: cssLen('min(2rem, 4vh) min(2.4rem, 4vw)'),
            textAlign: 'center',
            display: 'flex',
            flexDirection: 'column',
            ...gapVar(cssLen('min(1rem, 2.2vh)')),
            alignItems: 'center',
            maxWidth: '42rem',
            maxHeight: '100%',
            overflowY: 'auto',
          }}
        >
          <h2 style={{ margin: 0 }}>{t('parental.titleForgot')}</h2>

          {faltam > 0 ? (
            <p style={{ margin: 0, color: 'var(--danger)' }}>
              {t('parental.waiting', { secs: faltam })}
            </p>
          ) : etapa === 'senha' ? (
            <>
              <p style={{ margin: 0, color: 'var(--text-secondary)' }}>
                {t('parental.bodyForgotPassword')}
              </p>
              <strong style={{ fontSize: 'var(--fs-section)', minHeight: '1.5em' }}>
                {'•'.repeat(senha.length) || ' '}
              </strong>
              {erroSenha && (
                <p role="alert" style={{ margin: 0, color: 'var(--danger)' }}>
                  {erroSenha}
                  {attemptsLeft != null &&
                    ` · ${t('parental.attemptsLeft', { n: attemptsLeft })}`}
                </p>
              )}
              <OnScreenKeyboard
                focusKey="forgot-kb"
                onInput={(ch) => setSenha((s) => s + ch)}
                onDelete={() => setSenha((s) => s.slice(0, -1))}
                onClear={() => setSenha('')}
                onSubmit={confirmarSenha}
                submitLabel={t('common.confirm')}
              />
            </>
          ) : (
            <>
              <p style={{ margin: 0, color: 'var(--text-secondary)' }}>
                {t('parental.bodyForgotNewPin')}
              </p>
              <Marcadores preenchidos={pin.length} />
              <TecladoNumerico
                onDigit={digitarPin}
                onDelete={() => setPin((p) => p.slice(0, -1))}
              />
            </>
          )}

          <FocusButton focusKey="forgot-cancel" onPress={onCancel}>
            {t('common.cancel')}
          </FocusButton>
        </div>
      </div>
    </FocusContext.Provider>
  );
}

function Marcadores({ preenchidos }: Readonly<{ preenchidos: number }>) {
  return (
    <div className={gapRowClass} style={{ display: 'flex', ...gapVar('0.8rem') }} aria-hidden>
      {Array.from({ length: DIGITOS }, (_, i) => (
        <span
          key={i}
          style={{
            width: '0.9rem',
            height: '0.9rem',
            borderRadius: '50%',
            background: i < preenchidos ? 'var(--accent)' : 'transparent',
            border: '2px solid var(--border-strong)',
          }}
        />
      ))}
    </div>
  );
}

/** Teclado numérico 0-9 + apagar — mesmo layout do `PinModal`. */
function TecladoNumerico({
  onDigit,
  onDelete,
}: Readonly<{ onDigit: (d: string) => void; onDelete: () => void }>) {
  const linhas = [
    ['1', '2', '3'],
    ['4', '5', '6'],
    ['7', '8', '9'],
    ['⌫', '0'],
  ];
  return (
    <div
      className={gapColClass}
      style={{ display: 'flex', flexDirection: 'column', ...gapVar(cssLen('min(0.6rem, 1.4vh)')) }}
    >
      {linhas.map((linha, r) => (
        <div
          key={r}
          className={gapRowClass}
          style={{
            display: 'flex',
            justifyContent: 'center',
            ...gapVar(cssLen('min(0.6rem, 1.4vh)')),
          }}
        >
          {linha.map((d) => (
            <TeclaNumerica
              key={d}
              label={d === '⌫' ? <BackspaceIcon /> : d}
              focusKey={`forgot-pin-${d === '⌫' ? 'del' : d}`}
              onPress={() => (d === '⌫' ? onDelete() : onDigit(d))}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

function TeclaNumerica({
  label,
  focusKey,
  onPress,
}: Readonly<{ label: ReactNode; focusKey: string; onPress: () => void }>) {
  const { ref, focused } = useFocusable({ focusKey, onEnterPress: onPress });
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(focusKey, onPress)}
      style={{
        appearance: 'none',
        cursor: 'pointer',
        width: cssLen('min(3.4rem, 8vh)'),
        height: cssLen('min(3.4rem, 8vh)'),
        borderRadius: 'var(--radius-sm)',
        border: '1px solid var(--border-subtle)',
        background: focused ? 'var(--accent)' : 'var(--bg-raised)',
        color: focused ? 'var(--text-on-accent)' : 'var(--text-primary)',
        font: 'inherit',
        fontSize: '1.2em',
        ...focusRing(focused),
      }}
    >
      {label}
    </button>
  );
}
