import { useEffect, useState, type ReactNode } from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import { focusRing } from '../nav/focusRing.js';
import { useBackHandler } from '../nav/backStack.js';
import { pressWithFocus } from '../nav/pressWithFocus.js';
import { FocusButton } from './FocusButton.js';
import { BackspaceIcon } from './icons.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

export interface PinModalProps {
  title: string;
  /** Explicação curta do que vai acontecer ao confirmar. */
  body?: string;
  /** Quantas tentativas ainda restam antes da espera (RF-32). */
  attemptsLeft?: number;
  /** Instante (epoch ms) até quando novas tentativas são recusadas; 0 = liberado. */
  waitUntil?: number;
  /** Erro da última tentativa, já traduzido. */
  error?: string;
  onConfirm: (pin: string) => void;
  onCancel: () => void;
  /** Ausente = sem link "Esqueci o PIN" (fluxo de criação, por exemplo). */
  onForgot?: () => void;
}

const DIGITOS = 4;

/**
 * Modal de PIN (tela 12): 4 dígitos, teclado numérico, sobre o contexto atual.
 *
 * O desenho pede o fundo borrado; aqui é um véu escuro sólido — a constitution
 * §8 veta `blur` no hardware mínimo, onde ele custa caro em tela cheia.
 */
export function PinModal({
  title,
  body,
  attemptsLeft,
  waitUntil = 0,
  error,
  onConfirm,
  onCancel,
  onForgot,
}: Readonly<PinModalProps>) {
  const [pin, setPin] = useState('');
  const { ref, focusKey } = useFocusable({
    focusKey: 'pin-modal',
    trackChildren: true,
    saveLastFocusedChild: true,
  });

  useEffect(() => {
    setFocus('pin-1');
  }, []);

  // BACK fecha o modal — é o cancelar natural no controle remoto
  useBackHandler(onCancel);

  // conta o tempo de espera de verdade, em vez de receber um número congelado
  const [agora, setAgora] = useState(() => Date.now());
  useEffect(() => {
    if (waitUntil <= agora) return;
    const id = window.setInterval(() => setAgora(Date.now()), 500);
    return () => window.clearInterval(id);
  }, [waitUntil, agora]);
  const faltam = Math.max(0, Math.ceil((waitUntil - agora) / 1000));

  const digitar = (d: string) => {
    setPin((p) => {
      const novo = p.length >= DIGITOS ? p : p + d;
      if (novo.length === DIGITOS) {
        // limpa já: se o PIN estiver errado o campo volta vazio para a próxima
        // tentativa; se estiver certo, o modal fecha e nada disso aparece
        setTimeout(() => {
          onConfirm(novo);
          setPin('');
        }, 0);
      }
      return novo;
    });
  };

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        role="dialog"
        aria-modal
        aria-label={title}
        style={{
          position: 'fixed',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          zIndex: 50,
          background: 'var(--bg-scrim)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          // `padding: '5%'` parecia inofensivo mas porcentagem de padding
          // resolve contra a **largura**: num telefone deitado (842x387) davam
          // 42px em cima e embaixo, 84px de uma tela de 387. Em `vh`/`vw` cada
          // eixo usa a sua própria medida.
          padding: '2vh 4vw',
        }}
      >
        <div
          className={gapColClass}
          style={{
            background: 'var(--bg-panel)',
            border: '1px solid var(--border-subtle)',
            borderRadius: 'var(--radius-lg)',
            // Medidas presas ao `rem` estouravam a tela: no telefone deitado a
            // caixa dava 472px numa janela de 387 e o "0", o "⌫" e o Cancelar
            // ficavam inalcançáveis. Com `min()` o espaçamento cede onde falta
            // altura, e o `overflow` garante que nada fique fora de alcance nem
            // no pior caso.
            padding: cssLen('min(2rem, 4vh) min(2.4rem, 4vw)'),
            textAlign: 'center',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            ...gapVar(cssLen('min(1rem, 2.2vh)')),
            maxWidth: '32rem',
            maxHeight: '100%',
            overflowY: 'auto',
          }}
        >
          <div style={{ fontSize: cssLen('min(2.4em, 6vh)'), lineHeight: 1 }} aria-hidden>
            🔒
          </div>
          <h2 style={{ margin: 0 }}>{title}</h2>
          {body && (
            <p style={{ margin: 0, color: 'var(--text-secondary)' }}>{body}</p>
          )}

          <Marcadores preenchidos={pin.length} />

          {faltam > 0 ? (
            <p style={{ margin: 0, color: 'var(--danger)' }}>
              {t('parental.waiting', { secs: faltam })}
            </p>
          ) : (
            <>
              {error && (
                <p role="alert" style={{ margin: 0, color: 'var(--danger)' }}>
                  {error}
                  {attemptsLeft != null &&
                    ` · ${t('parental.attemptsLeft', { n: attemptsLeft })}`}
                </p>
              )}
              <Teclado onDigit={digitar} onDelete={() => setPin((p) => p.slice(0, -1))} />
            </>
          )}

          <div className={gapRowClass} style={{ display: 'flex', ...gapVar('0.6rem') }}>
            <FocusButton focusKey="pin-cancel" onPress={onCancel}>
              {t('common.cancel')}
            </FocusButton>
            {onForgot && faltam === 0 && (
              <FocusButton focusKey="pin-forgot" onPress={onForgot}>
                {t('parental.forgot')}
              </FocusButton>
            )}
          </div>
        </div>
      </div>
    </FocusContext.Provider>
  );
}

function Marcadores({ preenchidos }: Readonly<{ preenchidos: number }>) {
  return (
    <div className={gapRowClass} style={{ display: 'flex', ...gapVar('0.8rem') }} aria-hidden>
      {Array.from({ length: DIGITOS }, (_, i) => (
        <span
          key={i}
          style={{
            width: '0.9rem',
            height: '0.9rem',
            borderRadius: '50%',
            background: i < preenchidos ? 'var(--accent)' : 'transparent',
            border: '2px solid var(--border-strong)',
          }}
        />
      ))}
    </div>
  );
}

/** Teclado numérico 0-9 + apagar, navegável por D-pad. */
function Teclado({
  onDigit,
  onDelete,
}: Readonly<{ onDigit: (d: string) => void; onDelete: () => void }>) {
  const linhas = [
    ['1', '2', '3'],
    ['4', '5', '6'],
    ['7', '8', '9'],
    ['⌫', '0'],
  ];
  return (
    <div
      className={gapColClass}
      style={{ display: 'flex', flexDirection: 'column', ...gapVar(cssLen('min(0.6rem, 1.4vh)')) }}
    >
      {linhas.map((linha, r) => (
        <div
          key={r}
          className={gapRowClass}
          style={{
            display: 'flex',
            justifyContent: 'center',
            ...gapVar(cssLen('min(0.6rem, 1.4vh)')),
          }}
        >
          {linha.map((d) => (
            <Tecla
              key={d}
              label={d === '⌫' ? <BackspaceIcon /> : d}
              focusKey={`pin-${d === '⌫' ? 'del' : d}`}
              onPress={() => (d === '⌫' ? onDelete() : onDigit(d))}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

function Tecla({
  label,
  focusKey,
  onPress,
}: Readonly<{ label: ReactNode; focusKey: string; onPress: () => void }>) {
  const { ref, focused } = useFocusable({ focusKey, onEnterPress: onPress });
  return (
    <button
      ref={ref}
      type="button"
      onClick={pressWithFocus(focusKey, onPress)}
      style={{
        appearance: 'none',
        cursor: 'pointer',
        // mesma razão do espaçamento acima: encolhe só em tela baixa
        width: cssLen('min(3.4rem, 8vh)'),
        height: cssLen('min(3.4rem, 8vh)'),
        borderRadius: 'var(--radius-sm)',
        border: '1px solid var(--border-subtle)',
        background: focused ? 'var(--accent)' : 'var(--bg-raised)',
        color: focused ? 'var(--text-on-accent)' : 'var(--text-primary)',
        font: 'inherit',
        fontSize: '1.2em',
        ...focusRing(focused),
      }}
    >
      {label}
    </button>
  );
}
